  const THEMES_STYLE_KEYS = ['containerPadding', 'containerBorderStyle', 'containerBorderWidth', 'containerBorderRadius', 'containerShadowSize', 'containerBorderColor', 'fieldSize', 'fieldBorderStyle', 'fieldBorderRadius', 'fieldBorderSize', 'fieldBackgroundColor', 'fieldBorderColor', 'fieldTextColor', 'fieldMenuColor', 'pageBreakColor', 'labelSize', 'labelColor', 'labelSublabelColor', 'labelErrorColor', 'buttonSize', 'buttonBorderStyle', 'buttonBorderSize', 'buttonBorderRadius', 'buttonBackgroundColor', 'buttonBorderColor', 'buttonTextColor', 'backgroundColor', 'backgroundPosition', 'backgroundUrl', 'backgroundRepeat', 'backgroundSize', 'backgroundSizeMode', 'backgroundWidth', 'backgroundHeight', 'backgroundImage']; // common.min.js getStyleAttributesKeys
