    isTransparentColor(r, t = 0.33) { r = cssColors.getColorAsRGBArray(r); return Number(r?.[3]) <= t; },
    getContrastColor(r) { r = cssColors.getColorAsRGBArray(r); const t = r.reduce((a, b) => a + b, 0); return Math.round(t / 3 * (r[3] ?? 1)) < 150 ? '#ffffff' : '#000000'; },
