          ['content-initial', 'section-toggles'].forEach((k) => show(q('#wpforms-admin-form-embed-wizard-' + k), true));
          ['content-select-page', 'content-create-page', 'section-go', 'content-shortcode', 'section-goback'].forEach((k) => show(q('#wpforms-admin-form-embed-wizard-' + k), false));
