          const ta = document.getElementById(b.getAttribute('data-wp-editor-id')) || q('textarea', wrap), mce = q('.mce-tinymce', wrap);
          if (ta) { ta.style.display = html ? 'block' : 'none'; ta.removeAttribute('aria-hidden'); }
          if (mce) mce.style.display = html ? 'none' : '';
