  // ─── Add Fields palette search ────────────────────────────────────────────────────────────────────
  // @source wpforms/assets/js/admin/builder/search-fields.min.js:1 (setup / searchAction / clearSearch / cloneClickAction)
  function searchAction(input) {
    const list = q('.wpforms-search-fields-list .wpforms-add-fields-buttons');
    const listWrap = q('.wpforms-search-fields-list');
    const noRes = q('.wpforms-search-fields-no-results');
    const close = q('.wpforms-search-fields-input-close');
    const groups = qa('.wpforms-tab-content > .wpforms-add-fields-group');
    const term = input.value.toLowerCase();
    if (!list) return;
    list.innerHTML = '';
    if (!term) {
      groups.forEach((g) => { g.style.display = ''; });
      if (listWrap) listWrap.style.display = 'none';
      if (noRes) noRes.style.display = 'none';
      if (close) close.classList.remove('active');
      return;
    }
    groups.forEach((g) => { g.style.display = 'none'; });
    if (listWrap) listWrap.style.display = 'block';
    // Some captures baked the hidden state inline (style="display: none;"); .active alone shows it on live.
    if (close) { close.classList.add('active'); close.style.display = ''; }
    qa('.wpforms-tab-content > .wpforms-add-fields-group .wpforms-add-fields-button', builder() || document).forEach((btn) => {
      const text = btn.textContent.toLowerCase();
      const kw = (btn.getAttribute('data-field-keywords') || '').toLowerCase();
      if (text.indexOf(term) < 0 && !(kw && kw.indexOf(term) >= 0)) return;
      const c = btn.cloneNode(true);
      c.setAttribute('data-target', btn.id);
      c.removeAttribute('id');
      c.classList.add('wpforms-add-fields-button-clone');
      list.appendChild(c);
    });
    if (list.querySelector('.wpforms-add-fields-button')) {
      if (noRes) noRes.style.display = 'none';
    } else {
      if (noRes) noRes.style.display = 'block';
      if (listWrap) listWrap.style.display = 'none';
    }
  }
  function clearSearch() {
    const input = q('#wpforms-search-fields-input');
    if (!input || !input.value) return;
    const list = q('.wpforms-search-fields-list .wpforms-add-fields-buttons');
    if (list) list.innerHTML = '';
    const listWrap = q('.wpforms-search-fields-list');
    if (listWrap) listWrap.style.display = 'none';
    qa('.wpforms-tab-content > .wpforms-add-fields-group').forEach((g) => { g.style.display = ''; });
    const noRes = q('.wpforms-search-fields-no-results');
    if (noRes) noRes.style.display = 'none';
    input.value = '';
    input.focus();
    const close = q('.wpforms-search-fields-input-close');
    if (close) close.classList.remove('active');
  }

  // ─── ⋮ More menu (top bar) ────────────────────────────────────────────────────────────────────────
  // @source wpforms/assets/js/admin/builder/context-menu.min.js:1 (events / mainMenuItemClickAction / handleUrlAction /
  //         handleWhatsNewAction / hideMainContextMenu); markup includes/admin/builder/class-builder.php:1759
  const mainMenu = () => q('#wpforms-context-menu');
  function hideMainMenu() {
    const m = mainMenu();
    if (!m || !shown(m) || (m.__snapAnim && !m.__snapFadeShow)) return;
    fade(m, false, 150, () => { const c = q('#wpforms-context-menu-container'); if (c) c.classList.remove('wpforms-context-menu-active'); });
  }
  // A link the snapshot set carries opens that snapshot (live opens it in a new tab); core.js resolves it through nav.js.
  function hopTo(url, fallbackSlug) {
    const R = window.SnapRuntime;
    let slug = null;
    try { slug = R && typeof R.resolveHref === 'function' ? R.resolveHref(url) : null; } catch (e) { slug = null; }
    slug = slug || fallbackSlug;
    if (slug) S.navigate(slug);
    else console.info('[snap] no snapshot for ' + url + ' — live opens it in a new tab');
  }
  const formId = () => { const f = q('#wpforms-builder-form'); return f ? f.getAttribute('data-id') || '' : ''; };
  function mainMenuItemClickAction(item) {
    const act = item.getAttribute('data-action');
    const url = item.getAttribute('data-action-url') || '';
    const name = item.textContent.replace(/\s+/g, ' ').trim();
    if (act === 'duplicate-form' || act === 'save-as-template' || act === 'duplicate-template') {
      if (url) liveOnly(name + ' (the form is saved, then the server makes the copy and opens it)');
    } else if (act === 'view-entries' || act === 'view-payments' || act === 'view-analytics') {
      // Inactive items carry an empty url and do nothing (handleUrlAction).
      if (url) hopTo(url, act === 'view-entries' && /[?&]form_id=(\d+)/.test(url) ? 'admin-entries-list-' + RegExp.$1 : null);
    } else if (act === 'keyboard-shortcuts') {
      openKeyboardShortcutsModal();
    } else if (act === 'whats-new') {
      // The splash parked on the entry screens, shared (_shared/fragments/whats-new.js, core S.whatsNew).
      if (S.whatsNew) S.whatsNew(item); else notCaptured("What's New opens the splash modal from #tmpl-wpforms-splash-modal-content (templates/admin/splash/modal.php:21)");
    }
  }

  // ─── Keyboard Shortcuts modal ─────────────────────────────────────────────────────────────────────
  // @source wpforms/assets/js/admin/builder/modules/keyboard-shortcuts.min.js:1 (openKeyboardShortcutsModal: $.alert blue,
  //         fa-keyboard-o, 700px, closeIcon, backgroundDismiss, no buttons); list + strings src/Admin/Builder/Shortcuts.php:47-66,
  //         :82-83, template :95-118. Dialog built by WPFSnap.jconfirm (the captured jquery-confirm markup).
  const SHORTCUTS = [
    ['ctrl s', 'Save Form'], ['ctrl h', 'Open Help'], ['ctrl b', 'Embed Form'], ['ctrl t', 'Toggle Sidebar'],
    ['ctrl p', 'Preview Form'], ['ctrl q', 'Close Builder'], ['ctrl f', 'Search Fields'], ['ctrl e', 'View Entries'],
    ['ctrl c', 'Copy Field'], ['ctrl v', 'Paste Field'], ['d', 'Duplicate Field'], ['delete', 'Delete Field'],
    ['ctrl shift alt t', 'Move Field Up'], ['ctrl shift alt y', 'Move Field Down'], ['ctrl z', 'Undo'], ['ctrl shift z', 'Redo'],
  ];
  // The captures carry the pre-2.0.2.1 stylesheet (two .wpforms-column lists); the row-major .wpforms-shortcuts grid is styled
  // by the plugin's own rules: wpforms/assets/css/builder/builder-third-party.min.css (the .wpforms_page_wpforms-builder variants).
  const KS = '.wpforms_page_wpforms-builder .jconfirm .jconfirm-box-container .jconfirm-box.wpforms-builder-keyboard-shortcuts';
  const KS_CSS = 'K{max-width:100%}K .jconfirm-content-pane{max-height:calc(100vh - 333px);transition-property:max-height;transition-duration:.25s;transition-timing-function:ease-out}K .jconfirm-title-c{margin-bottom:15px}K .jconfirm-closeIcon{inset-inline-end:28px;top:28px}K .wpforms-shortcuts{border:1px solid #c3c4c7;border-radius:6px;display:grid;grid-template-columns:repeat(2, 1fr);margin:30px 0 0 0;overflow:hidden}K .wpforms-shortcuts li{border-bottom:1px solid #dcdcde;font-size:14px;line-height:30px;margin:0;padding:8px 10px;text-align:start;display:flex}K .wpforms-shortcuts li:nth-child(odd){border-inline-end:1px solid #dcdcde}K .wpforms-shortcuts li:nth-last-child(-n+2){border-bottom:none}K .wpforms-shortcuts li span{margin-inline-start:auto;text-align:end;white-space:nowrap}K .wpforms-shortcuts li span i{background-color:#ebf3fc;border-radius:4px;color:#036aab;display:inline-block;font-style:normal;line-height:16px;margin-inline-start:5px;min-width:30px;padding:5px 10px;text-transform:capitalize}K .wpforms-shortcuts li span i:empty{display:none}@media(max-width: 767px){K .wpforms-shortcuts li:nth-child(odd){border-inline-end:none}K .wpforms-shortcuts li:nth-last-child(-n+2){border-bottom:1px solid #dcdcde}K .wpforms-shortcuts li:last-child{border-bottom:none}}@media(max-width: 767px){K .wpforms-shortcuts{grid-template-columns:1fr}}';
  function openKeyboardShortcutsModal() {
    if (!document.getElementById('wpf-snap-shortcuts-css')) {
      const st = document.createElement('style');
      st.id = 'wpf-snap-shortcuts-css';
      st.textContent = KS_CSS.split('K').join(KS);
      document.head.appendChild(st);
    }
    if (q('.jconfirm .wpforms-builder-keyboard-shortcuts')) {
      // A second trigger closes the last dialog (jconfirm.instances[last].close()).
      const all = qa('.jconfirm[data-snap-jc-root]');
      if (all.length) S.jcClose(all[all.length - 1], -1);
      return;
    }
    const list = '<ul class="wpforms-shortcuts">' + SHORTCUTS.map(([k, label]) => '<li>' + label + '<span class="shortcut-key shortcut-key-' + k.replace(/ /g, '-') + '">' + k.split(' ').map((p) => '<i>' + p + '</i>').join('') + '</span></li>').join('') + '</ul>';
    const m = typeof S.jconfirm === 'function' ? S.jconfirm({ title: 'Keyboard Shortcuts', icon: 'fa fa-keyboard-o', type: 'blue', boxWidth: '700px', content: 'Handy shortcuts for common actions in the builder.' + list, buttons: [] }) : null;
    if (!m) return;
    const box = m.querySelector('.jconfirm-box');
    box.classList.add('wpforms-builder-keyboard-shortcuts');
    // onOpenBefore: Mac swaps the key glyphs; Windows / Linux show Alt+S for Toggle Sidebar.
    if (isMac()) {
      const glyph = { shift: '⇧', alt: '⌥' };
      qa('.shortcut-key i', box).forEach((i) => {
        const t = i.textContent;
        if (glyph[t]) i.textContent = glyph[t];
        else if (t === 'ctrl' && !i.parentElement.matches('.shortcut-key-ctrl-h, .shortcut-key-ctrl-q, .shortcut-key-ctrl-t')) i.textContent = '⌘';
      });
    } else {
      const t = box.querySelector('.shortcut-key.shortcut-key-ctrl-t');
      if (t) t.innerHTML = '<i>alt</i><i>s</i>';
    }
    const ci = m.querySelector('.jconfirm-closeIcon');
    if (ci) { ci.style.display = 'block'; ci.addEventListener('click', () => S.jcClose(m, -1)); }
    const btns = m.querySelector('.jconfirm-buttons');
    if (btns) btns.style.display = 'none';
    m.addEventListener('click', (e) => { if (!(e.target instanceof Element) || !e.target.closest('.jconfirm-box')) S.jcClose(m, -1); });
    // jquery-confirm _updateContentMaxHeight: window height − box chrome − offsetTop / offsetBottom (40 + 40).
    const pane = m.querySelector('.jconfirm-content-pane');
    if (pane) {
      pane.style.maxHeight = Math.max(0, window.innerHeight - (box.offsetHeight - pane.offsetHeight) - 80) + 'px';
      pane.classList.toggle('no-scroll', pane.scrollHeight <= pane.clientHeight);
    }
  }

