  function openHelp(btn) {
    const help = q('#wpforms-builder-help');
    if (!help) { notCaptured('the Help overlay (templates/builder/help.php:28) is not in this capture — park it'); return; }
    document.body.classList.add('wpforms-builder-help-open');
    const cats = q('#wpforms-builder-help-categories');
    const first = cats && cats.querySelector('.wpforms-builder-help-category');
    const term = btn.getAttribute('data-search-term') || HELP_TERMS[helpContext()] || '';
    if (term !== '' || (first && first.classList.contains('opened'))) {
      qa('.wpforms-builder-help-category', cats).forEach((c) => c.classList.remove('opened'));
      qa('.wpforms-builder-help-docs', cats).forEach((d) => slide(d, false, 400));
    } else if (first && first.querySelector('header')) {
      toggleHelpCategory(first.querySelector('header'));
    }
    const input = q('#wpforms-builder-help-search input');
    if (input) { input.value = term; debounce250(helpSearch); }
    helpFadeIn(help);
    setTimeout(() => {
      helpFadeIn(q('#wpforms-builder-help-result'));
      helpFadeIn(cats);
      helpFadeIn(q('#wpforms-builder-help-footer'));
    }, 300);
  }
  function closeHelp() {
    document.body.classList.remove('wpforms-builder-help-open');
    ['#wpforms-builder-help-result', '#wpforms-builder-help-categories', '#wpforms-builder-help-footer', '#wpforms-builder-help'].forEach((s) => helpFadeOut(q(s)));
  }

