    const install = act === 'install';
    const content = btn.getAttribute('data-message') || '<p>' + EDU_ESC((install ? 'The %name% is not installed. Would you like to install and activate it?' : 'The %name% is installed but not activated. Would you like to activate it?').replace(/%name%/g, name)) + '</p>';
