    const m = S.jconfirm({ title: false, icon: 'fa fa-info-circle', type: 'blue', boxWidth: install ? '425px' : '400px', content,
      buttons: [{ text: install ? 'Yes, Install and Activate' : 'Yes, Activate', cls: 'btn-confirm', action: () => { liveOnly((install ? 'wpforms_install_addon' : 'wpforms_activate_addon') + ' (' + name + ') and the builder reload'); } },
        { text: 'Cancel' }] });
