    const btns = (o.buttons || []).map((b, i) => '<button type="button" class="btn ' + (b.cls || 'btn-default') + '" data-snap-jc="' + i + '">' + b.text + '</button>').join('');
    const icon = o.icon ? '<i class="' + o.icon + '"></i>' : '';
