  document.addEventListener('focusin', (e) => { const m = e.target instanceof Element && e.target.classList.contains('minicolors-input') ? mcOf(e.target) : null; if (m) mcShow(m); });
  document.addEventListener('keydown', (e) => { if (mcOpen && (e.key === 'Escape' || e.key === 'Tab')) mcHide(mcOpen); });
  // The swatch follows a typed colour (minicolors keyup → updateFromInput).
  document.addEventListener('input', (e) => {
    const t = e.target; const m = t instanceof Element && t.classList.contains('minicolors-input') ? mcOf(t) : null; if (!m) return;
    const sw = q('.minicolors-swatch-color', m); if (sw && validColor(t.value)) sw.style.backgroundColor = t.value;
  });

  // Non-bubbling / keyboard events the dispatcher does not carry (blur, keyup, focus).
  // camera.min.js · validateTimeLimitMinutes / validateTimeLimitSeconds / validateRatioWidth / validateRatioHeight (blur);
  // file-upload.min.js · cleanPasswordButtonHandler (keyup focus) / checkPasswordMatch (keyup).
  document.addEventListener('focusout', (e) => {
    const t = e.target;
    if (!(t instanceof HTMLInputElement) || !at(t, '.wpforms-field-option')) return;
    const p = at(t, '.wpforms-field-option');
    const int = (v) => parseInt(v, 10);
    if (t.classList.contains('wpforms-file-upload-camera-time-limit-minutes-input')) {
      const s = q('.wpforms-file-upload-camera-time-limit-seconds-input', p); let a = int(t.value); const sv = s ? int(s.value) : NaN;
      if (isNaN(a)) a = 0; if (a < 0) a = 0; t.value = a; if (a === 0 && (isNaN(sv) || sv === 0) && s) s.value = 1;
    } else if (t.classList.contains('wpforms-file-upload-camera-time-limit-seconds-input')) {
      const m = q('.wpforms-file-upload-camera-time-limit-minutes-input', p); let a = int(t.value); const mv = m ? int(m.value) : NaN;
      if (isNaN(a)) a = 0; if (a < 0) a = 0; else if (a > 59) a = 59; t.value = a; if (a === 0 && (isNaN(mv) || mv === 0)) t.value = 1;
    } else if (t.classList.contains('wpforms-file-upload-camera-ratio-width-input') || t.classList.contains('wpforms-file-upload-camera-ratio-height-input')) {
      let a = int(t.value); if (isNaN(a)) a = 1; if (a < 1) a = 1; t.value = a;
    }
  });
