  // ═══ Small settings / tools inputs ═════════════════════════════════════════════════════════════════════
  // wpforms/includes/admin/settings-api.php:230-250 wpforms_settings_masked_text_callback renders value = the masked
  // string (the capture serialized value=""); masked-input.min.js · handleFocus / handleBlur swap it with the editable field.
  ready(() => qa('.wpforms-admin-settings input[data-masked="1"]').forEach((i) => { if (!i.value && i.hasAttribute('readonly')) i.value = i.getAttribute('data-masked-value') || ''; }));
  const maskedOff = (i) => { const f = q('.wpforms-masked-input-clear-flag', at(i, '.wpforms-masked-input-wrap')); return f && f.value === '1'; };
  document.addEventListener('focusin', (e) => {
    const i = e.target; if (!(i instanceof HTMLInputElement) || !i.matches('.wpforms-admin-settings input[data-masked="1"]') || maskedOff(i)) return;
    i.removeAttribute('readonly'); i.value = ''; i.setAttribute('placeholder', i.getAttribute('data-masked-placeholder') || ''); i.setAttribute('name', i.getAttribute('data-name') || '');
  });
  document.addEventListener('focusout', (e) => {
    const i = e.target; if (!(i instanceof HTMLInputElement) || !i.matches('.wpforms-admin-settings input[data-masked="1"]') || maskedOff(i) || i.value.trim() !== '') return;
    i.value = i.getAttribute('data-masked-value') || ''; i.setAttribute('readonly', ''); i.removeAttribute('placeholder'); i.removeAttribute('name');
  });
  // wpforms/assets/js/admin/admin.min.js · ready() .wpforms-file-upload: the label's .fld shows the chosen file name
  // (or data-multiple-caption with the count); no file restores the label.
  document.addEventListener('change', (e) => {
    const i = e.target; if (!(i instanceof HTMLInputElement) || i.type !== 'file' || !at(i, '.wpforms-file-upload')) return;
    const l = q('label', at(i, '.wpforms-file-upload')); if (!l) return;
    if (l.__snapOrig === undefined) l.__snapOrig = l.innerHTML;
    const n = i.files && i.files.length > 1 ? (i.getAttribute('data-multiple-caption') || '').replace('{count}', i.files.length) : (i.value ? i.value.split('\\').pop() : '');
    const fld = q('.fld', l);
    if (n && fld) fld.innerHTML = esc(n); else if (!n) l.innerHTML = l.__snapOrig;
  });

  // ═══ Surveys & Polls report menus (entries list of a survey form, survey results) ════════════════════════
  // wpforms-surveys-polls/assets/js/admin-survey-reporting.js:727-776 (context menus toggle
