  // handleImportDataLoaded (step2.show, or the file notice for a file_validation error) → resetContinueButton.
  function impLoad() {
    const btn = q('#wpforms_entries_import_submit');
    if (impSource() !== 'export_file') {
      const pl = q('#wpforms_entries_import_plugin'), sf = q('#wpforms_entries_import_source_form'), df = q('#wpforms_entries_import_destination_form_from_plugin');
      if (pl && sf && df && pl.value && sf.value && df.value) liveOnly('Continue loads the fields of the ' + pl.value + ' source form (wpforms_import_load_plugin_import) — not part of this snapshot');
      return;
    }
    const input = q('#wpforms_entries_import_file'), dest = q('#wpforms_entries_import_destination_form_export_file');
    if (!btn || !input || !input.files || !input.files[0] || !dest || !dest.value) return;
    btn.disabled = true; btn.textContent = 'Loading…';
    const id = dest.value;
    WS.fragment('import-mapping').then((fr) => {
      const d = fragData(fr);
      setTimeout(() => {
        const f = d && d.forms && d.forms[id];
        if (!d) notCaptured('import-mapping fragment (the field mapping after Continue, wpforms_import_load_file_import)');
        else if (!f) notCaptured('import-mapping for form ' + id + ' (the field mapping after Continue)');
        else if (f.error) impNotice(f.error, q('.wpforms-entries-import-file-notices'));
        else impShow({ sourceFields: d.source_fields || [], destinationFields: f.destination_fields || [], totalRows: d.total, unsupportedFieldsNotice: f.unsupported_fields_notice, entriesUrl: d.entries_url });
        btn.disabled = false; btn.textContent = 'Continue';
      }, 300);
    });
  }
  // form.step2.show
  function impShow(e) {
    IMP.total = e.totalRows || 0;
    impPopulate(e);
    impTotalInfo(e.totalRows, e.entriesUrl);
    const n2 = q('.wpforms-entries-import-step2-notices');
    if (typeof e.unsupportedFieldsNotice === 'string' && e.unsupportedFieldsNotice !== '') impNotice(e.unsupportedFieldsNotice, n2, 'warning');
    else if (n2) n2.innerHTML = '';
    qa('.wpforms-entries-import-step1-actions').forEach((x) => x.classList.add('wpforms-hidden'));
    const b = q('#wpforms-entries-import-mapping-block'); if (b) b.classList.remove('wpforms-hidden');
    impInitStatus();
  }
  // form.step2.populateTable (row markup verbatim; a "Source Meta / Destination Meta" header before the first meta row).
  function impPopulate(e) {
    const body = q('#wpforms-entries-import-mapping-body');
    if (!body) return;
    const map = impBuildMapping(e.destinationFields, e.sourceFields);
    let meta = false;
    const out = [];
    e.destinationFields.forEach((f) => {
      const t = map.has(f.key) ? map.get(f.key) : '';
      const def = (f.default && f.default.value != null) ? f.default.value : '';
      const cls = (t !== '' || def !== '') ? 'wpforms-entries-import-row-mapped' : 'wpforms-entries-import-row-unmapped';
      if (f && f.type === 'meta' && !meta) {
        meta = true;
        out.push(`<div class="wpforms-entries-import-mapping-header wpforms-entries-import-meta-header">
									<div class="wpforms-entries-import-col-source">Source Meta</div>
									<div class="wpforms-entries-import-col-arrow"></div>
									<div class="wpforms-entries-import-col-destination">Destination Meta</div>
								</div>`);
      }
      const first = f.default ? `<option value="${escU(f.default.value)}">${escU(f.default.label)}</option>` : '<option value="">--- Select a Field ---</option>';
      const opts = e.sourceFields.map((s) => `<option value="${escU(s.key)}"${s.key === t ? ' selected' : ''}>${escU(s.label)}</option>`).join('');
      out.push(`<div class="wpforms-entries-import-mapping-row ${cls}" data-field-key="${escU(f.key)}">
								<div class="wpforms-entries-import-col-source">
									<select class="wpforms-entries-import-source-select" data-field-key="${escU(f.key)}" name="wpforms_entries_import_map[${escU(f.key)}]">
										${first}
										${opts}
									</select>
								</div>
								<div class="wpforms-entries-import-col-arrow">&rarr;</div>
								<div class="wpforms-entries-import-col-destination">${escU(f.label)}</div>
							</div>`);
    });
    body.innerHTML = out.join('');
  }
  // helpers.normalizeFieldLabel / getLabelLastToken / getLabelParent / getDiceSimilarity / getTokenSetDiceSimilarity
  const impNorm = (s) => String(s).toLowerCase().split(': ').join(' ').split('/').join(' ').replace(/\s+/g, ' ').trim();
  const impLast = (s) => { const t = s.split(' ').filter(Boolean); return t.length ? t[t.length - 1] : ''; };
  const impParent = (s) => { const i = String(s).lastIndexOf(': '); return i === -1 ? '' : impNorm(String(s).slice(0, i)); };
  function impDice(a, b) {
    if (a.length < 2 || b.length < 2) return 0;
    const grams = (s) => { const m = new Map(); for (let i = 0; i < s.length - 1; i++) { const g = s.substring(i, i + 2); m.set(g, (m.get(g) || 0) + 1); } return m; };
    const ga = grams(a), gb = grams(b);
    let n = 0;
    ga.forEach((c, g) => { n += Math.min(c, gb.get(g) || 0); });
    return 2 * n / (a.length - 1 + b.length - 1);
  }
  function impTokenDice(a, b) {
    const sa = new Set(a.split(' ').filter(Boolean)), sb = new Set(b.split(' ').filter(Boolean));
    if (!sa.size || !sb.size) return 0;
    let n = 0;
    sa.forEach((t) => { if (sb.has(t)) n++; });
    return 2 * n / (sa.size + sb.size);
  }
  // form.step2.buildFieldMapping + addParentMatchCandidate + applyCanonicalParentBoost + greedyAssignMapping
  function impBuildMapping(dest, src) {
    const cand = [], parents = new Map();
    dest.forEach((df, di) => {
      const dl = impNorm(df.label);
      if (!dl) return;
      const last = impLast(dl), par = impParent(df.label);
      src.forEach((sf) => {
        const sl = impNorm(sf.label);
        if (!sl) return;
        const score = dl === sl ? 1 : Math.max(impDice(dl, sl), impTokenDice(dl, sl));
        const lastMatch = last !== '' && impLast(sl) === last ? 1 : 0;
        if (par !== '' && sl === par) {
          const k = par + '|' + sf.key;
          if (!parents.has(k)) parents.set(k, []);
          parents.get(k).push({ destKey: df.key, srcKey: sf.key, destIndex: di, score, lastTokenMatch: lastMatch });
        }
        if (score >= 0.5) cand.push({ destKey: df.key, srcKey: sf.key, score, lastTokenMatch: lastMatch });
      });
    });
    parents.forEach((list) => {
      if (list.some((x) => x.lastTokenMatch === 1)) return;
      list.sort((x, y) => x.destIndex - y.destIndex);
      const first = list[0];
      const best = Math.max(first.score, list.reduce((m, x) => Math.max(m, x.score), 0));
      const hit = cand.find((x) => x.destKey === first.destKey && x.srcKey === first.srcKey);
      if (hit) hit.score = best; else cand.push({ destKey: first.destKey, srcKey: first.srcKey, score: best, lastTokenMatch: 0 });
    });
    cand.sort((x, y) => y.score - x.score || y.lastTokenMatch - x.lastTokenMatch);
    const map = new Map(), usedD = new Set(), usedS = new Set();
    cand.forEach((c) => { if (usedD.has(c.destKey) || usedS.has(c.srcKey)) return; map.set(c.destKey, c.srcKey); usedD.add(c.destKey); usedS.add(c.srcKey); });
    return map;
  }
  // form.step2.updateTotalEntriesInfo + getEntriesText + buildSourceHtml (export file) + buildDestinationHtml (the
  // destination's entries link, wpforms_entries_import.entries_url, Import.php:140).
  function impTotalInfo(total, entriesUrl) {
    const dest = q('#wpforms_entries_import_destination_form_export_file');
    IMP.destId = dest ? dest.value : '';
    const c = dest && at(dest, '.choices');
    const it = c && qa('.choices__list--dropdown .choices__item--choice', c).find((x) => x.getAttribute('data-value') === IMP.destId);
    const nm = it && q('.wpforms-entries-import-form-name', it);
    const opt = dest && dest.options[dest.selectedIndex];
    IMP.destName = (nm ? nm.textContent : (opt ? opt.textContent : '')).trim();
    const src = '<strong>' + escU('the export file') + '</strong>';
    const name = escU(IMP.destName);
    const safe = (u) => { u = String(u || '').trim(); return /^https?:\/\//i.test(u) || u.startsWith('/') || u.startsWith('#') ? u : '#'; };
    const dst = entriesUrl && IMP.destId ? '<strong><a href="' + encodeURI(safe(entriesUrl + IMP.destId)) + '" target="_blank" rel="noopener noreferrer">' + name + '</a></strong>' : '<strong>' + name + '</strong>';
    const n = parseInt(total, 10) || 0;
    const ent = '<strong>' + n + (n === 1 ? ' entry' : ' entries') + '</strong>';
    const tpl = impSource() === 'export_file' ? "You're about to import {entries} to {destination}." : "You're about to import {entries} from {source} to {destination}.";
    const box = q('#wpforms-entries-import-total-text');
    if (box) box.innerHTML = tpl.replace('{entries}', ent).replace('{source}', src).replace('{destination}', dst);
  }
  // form.step2.initStatus / updateStatus / updateStatusText
  function impInitStatus() {
    IMP.totalFields = qa('#wpforms-entries-import-mapping-body .wpforms-entries-import-source-select').length;
    const t = q('#wpforms-entries-import-total-fields'); if (t) t.textContent = IMP.totalFields;
    impUpdateStatus();
  }
  function impUpdateStatus() {
    const n = qa('#wpforms-entries-import-mapping-body .wpforms-entries-import-source-select').filter((s) => s.value !== '').length;
    const skip = IMP.totalFields - n, all = n === IMP.totalFields && IMP.totalFields > 0;
    const ib = q('#wpforms-entries-import-submit'); if (ib) ib.disabled = n === 0;
    const r = all ? (IMP.totalFields === 1 ? 'All 1 field is mapped and your data is ready to be imported.' : 'All ' + IMP.totalFields + ' fields are mapped and your data is ready to be imported.')
      : n + ' of ' + IMP.totalFields + ' fields are mapped, ' + skip + ' fields will be skipped during import.';
    qa('.wpforms-entries-import-status').forEach((s) => {
      s.innerHTML = '<i id="wpforms-entries-import-status-icon" class="fa ' + (all ? 'fa-check-circle' : 'fa-exclamation-triangle') + '" aria-hidden="true"></i> ' + r;
      s.classList.toggle('wpforms-entries-import-status-all-mapped', all);
    });
  }

