  // ═══ 8. Phone (smart): country typed as "+<dial code>"; dropdown on pages without frontend.js ═══════════════
  // @since 2026-10-06 @source wpforms/assets/pro/js/frontend/fields/phone.min.js initSmartField (intlTelInput:
  //   _updateCountryFromNumber on input, selected-country flag + aria-label) @verified 2026-10-06 @product wpforms
  function setItiCountry(iti, item) {
    const flag = iti.querySelector('.iti__selected-country-primary .iti__flag');
    const code = item.getAttribute('data-country-code');
    if (flag && code) {
      Array.from(flag.classList).forEach((c) => { if (c !== 'iti__flag' && c.indexOf('iti__') === 0) flag.classList.remove(c); });
      flag.classList.add('iti__' + code);
    }
    const name = (item.querySelector('.iti__country-name') || {}).textContent || '';
    const dial = (item.querySelector('.iti__dial-code') || {}).textContent || '';
    const btn = iti.querySelector('.iti__selected-country');
    if (btn) { btn.setAttribute('aria-label', 'Change country, selected ' + name + ' (' + dial + ')'); btn.setAttribute('title', name); }
    $$('.iti__country', iti).forEach((li) => { li.classList.remove('iti__highlight'); li.setAttribute('aria-selected', 'false'); });
    item.classList.add('iti__highlight');
    item.setAttribute('aria-selected', 'true');
  }
  function smartPhoneTyped(el) {
    if (!el.classList.contains('wpforms-smart-phone-field')) return;
    const m = /^\+(\d{1,4})/.exec(el.value.replace(/[\s()-]/g, ''));
    const iti = el.closest('.iti');
    if (!m || !iti) return;
    const digits = m[1];
    const cur = iti.querySelector('.iti__country.iti__highlight') || iti.querySelector('.iti__country[aria-selected="true"]');
    let best = null;
    $$('.iti__country', iti).forEach((li) => {
      const d = li.getAttribute('data-dial-code');
      if (!d || digits.indexOf(d) !== 0) return;
      if (!best || d.length > best.getAttribute('data-dial-code').length) best = li;
    });
    if (!best) return;
    // Shared dial codes (+1, +7, +44 …): keep the selected country when it already owns the code.
    if (cur && cur.getAttribute('data-dial-code') === best.getAttribute('data-dial-code')) return;
    const flag = iti.querySelector('.iti__selected-country-primary .iti__flag');
    if (flag && flag.classList.contains('iti__' + best.getAttribute('data-country-code'))) return;
    setItiCountry(iti, best);
  }
  // frontend.js section 3 owns the dropdown where it loads; this is the same behaviour for the pages without it.
  // @since 2026-10-06 @source intl-tel-input (loaded by phone.min.js): toggle #iti-N__dropdown-content iti__hide,
  //   aria-expanded, pick → flag + aria-label, outside click closes @verified 2026-10-06 @product wpforms
  document.addEventListener('click', (e) => {
    if (hasFrontendJs()) return;
    const t = e.target;
    if (!(t instanceof Element)) return;
    const closeAll = () => {
      $$('.iti__dropdown-content').forEach((d) => d.classList.add('iti__hide'));
      $$('.iti__selected-country').forEach((b) => b.setAttribute('aria-expanded', 'false'));
      $$('.iti__arrow').forEach((a) => a.classList.remove('iti__arrow--up'));
    };
    const item = t.closest('.iti__country');
    if (item) { setItiCountry(item.closest('.iti'), item); closeAll(); return; }
    const btn = t.closest('.iti__selected-country');
    if (btn) {
      const dd = btn.closest('.iti').querySelector('.iti__dropdown-content');
      const wasOpen = dd && !dd.classList.contains('iti__hide');
      closeAll();
      if (dd && !wasOpen) {
        dd.classList.remove('iti__hide');
        btn.setAttribute('aria-expanded', 'true');
        const arrow = btn.querySelector('.iti__arrow');
        if (arrow) arrow.classList.add('iti__arrow--up');
      }
      return;
    }
    if (!t.closest('.iti__dropdown-content')) closeAll();
  });

