  // ═══ 9. Payments: Total, PayPal Commerce method ═══════════════════════════════════════════════════════════════
  // @since 2026-10-06 @source wpforms/assets/js/frontend/wpforms.min.js amountTotal / amountTotalCalc /
  //   getPaymentFieldAmount / getPaymentFieldQuantity / amountFormat / amountFormatSymbol / getCurrency (USD default:
  //   "$" left, 2 decimals, "," thousands); src/Forms/Fields/PaymentTotal/Field.php:76,361 @verified 2026-10-06 @product wpforms
  function amountSanitize(v) { return Number(String(v).replace('$', '').replace(/[^0-9.,]/g, '').replace(/,/g, '')) || 0; }
  function amountFormatSymbol(n) {
    const fixed = (Math.round(n * 100) / 100).toFixed(2);
    const [i, d] = fixed.split('.');
    return '$' + i.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + d;
  }
  function amountTotal(el) {
    const form = formOf(el);
    if (!form) return;
    let total = 0;
    $$('.wpforms-payment-price', form).forEach((p) => {
      if (p.closest('.wpforms-conditional-hide')) return;
      const t = (p.getAttribute('type') || '').toLowerCase();
      let amount = 0;
      if (t === 'text' || t === 'hidden') amount = amountSanitize(p.value);
      else if ((t === 'radio' || t === 'checkbox') && p.checked) amount = amountSanitize(p.getAttribute('data-amount'));
      else if (p.tagName === 'SELECT' && p.selectedOptions[0] && p.selectedOptions[0].getAttribute('data-amount')) amount = amountSanitize(p.selectedOptions[0].getAttribute('data-amount'));
      const q = p.id && document.getElementById(p.id + '-quantity');
      total += amount * (q ? Number(q.value) : 1);
    });
    const text = amountFormatSymbol(total);
    $$('.wpforms-payment-total', form).forEach((n) => {
      const t = (n.getAttribute('type') || '').toLowerCase();
      if (t === 'hidden' || t === 'text') n.value = text; else n.textContent = text;
    });
  }
  // @since 2026-10-06 @source wpforms/assets/js/integrations/paypal-commerce/wpforms-paypal-commerce.min.js
  //   paymentMethodToggle (card fields only for credit_card, fastlane fields only for fastlane, .wpforms-submit hidden
  //   and the single PayPal button shown for checkout) @verified 2026-10-06 @product wpforms
  function paypalMethodToggle(sel) {
    const form = formOf(sel);
    const v = sel.value;
    $$('.wpforms-paypal-commerce-card-fields', form).forEach((x) => x.classList.toggle('wpforms-hidden', v !== 'credit_card'));
    $$('.wpforms-paypal-commerce-fastlane-fields', form).forEach((x) => x.classList.toggle('wpforms-hidden', v !== 'fastlane'));
    $$('.wpforms-submit', form).forEach((x) => x.classList.toggle('wpforms-hidden', v === 'checkout'));
    $$('.wpforms-paypal-commerce-single-submit-button', form).forEach((x) => x.classList.toggle('wpforms-hidden', v !== 'checkout'));
    if (v === 'checkout' && !form.querySelector('.wpforms-paypal-commerce-single-submit-button')) liveOnly('PayPal Checkout button (rendered by the PayPal SDK)');
  }

